export interface AdminNotificationData {
  name: string;
  email: string;
  phone?: string;
  message: string;
  date?: string;
  inquiryId?: string;
  portalUrl?: string;
  companyName?: string;
  service?: string;
}

export function renderAdminNotificationHtml(data: AdminNotificationData): string {
  const formattedDate = data.date || new Date().toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });

  const name = escapeHtml(data.name || 'Valued Client');
  const companyName = escapeHtml(data.companyName || 'Not specified');
  const email = escapeHtml(data.email || '');
  const phone = escapeHtml(data.phone || 'Not provided');
  const service = escapeHtml(data.service || 'General Inquiry');
  const submissionDate = escapeHtml(formattedDate);
  const message = escapeHtml(data.message || 'No message provided');

  return RAW_TEMPLATE
    .replace(/{{name}}/g, name)
    .replace(/{{company_name}}/g, companyName)
    .replace(/{{email}}/g, email)
    .replace(/{{phone}}/g, phone)
    .replace(/{{service}}/g, service)
    .replace(/{{submission_date}}/g, submissionDate)
    .replace(/{{message}}/g, message);
}

function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

